CREATE TABLE public.prelaunch_work_history(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),client_id uuid NOT NULL REFERENCES public.clients(id),pipeline_id uuid NOT NULL REFERENCES public.pipelines(id),work_date date NOT NULL,description text NOT NULL,evidence_url text,entered_by uuid NOT NULL REFERENCES public.profiles(id),created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT ON public.prelaunch_work_history TO authenticated; GRANT ALL ON public.prelaunch_work_history TO service_role;
ALTER TABLE public.prelaunch_work_history ENABLE ROW LEVEL SECURITY;
CREATE POLICY history_read ON public.prelaunch_work_history FOR SELECT TO authenticated USING(can_view_client(client_id) AND NOT has_role(auth.uid(),'client'));
CREATE POLICY history_insert ON public.prelaunch_work_history FOR INSERT TO authenticated WITH CHECK(entered_by=auth.uid() AND NOT has_role(auth.uid(),'client') AND can_view_client(client_id) AND (is_manager(auth.uid()) OR can_edit_client(client_id) OR EXISTS(SELECT 1 FROM client_staff_assignments a WHERE a.client_id=prelaunch_work_history.client_id AND a.pipeline_id=prelaunch_work_history.pipeline_id AND a.user_id=auth.uid() AND NOT a.excluded)));
CREATE FUNCTION public.record_prelaunch_work(_client uuid,_pipeline uuid,_date date,_description text,_evidence text DEFAULT NULL) RETURNS uuid LANGUAGE plpgsql SECURITY INVOKER SET search_path=public AS $$ DECLARE i uuid; d date; BEGIN IF coalesce(trim(_description),'')='' THEN RAISE EXCEPTION 'Describe what was done'; END IF; IF nullif(trim(_evidence),'') IS NOT NULL AND _evidence !~ '^https://' THEN RAISE EXCEPTION 'Evidence must be an HTTPS link'; END IF; SELECT coalesce(launch_date,day0_date,contract_start) INTO d FROM client_launches WHERE client_id=_client AND status IN('active','live','on_hold','offboarding') ORDER BY created_at DESC LIMIT 1; IF d IS NOT NULL AND _date>=d THEN RAISE EXCEPTION 'Pre-launch history must be dated before the launch date'; END IF; INSERT INTO prelaunch_work_history(client_id,pipeline_id,work_date,description,evidence_url,entered_by) VALUES(_client,_pipeline,_date,trim(_description),nullif(trim(_evidence),''),auth.uid()) RETURNING id INTO i; RETURN i; END $$;
REVOKE ALL ON FUNCTION public.record_prelaunch_work(uuid,uuid,date,text,text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.record_prelaunch_work(uuid,uuid,date,text,text) TO authenticated;
CREATE TABLE public.staff_digest_outbox(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES public.profiles(id),slot_at timestamptz NOT NULL,to_address text,subject text NOT NULL,body text NOT NULL,items jsonb NOT NULL,held boolean NOT NULL DEFAULT true,created_at timestamptz NOT NULL DEFAULT now(),sent_at timestamptz,error text,attempts integer NOT NULL DEFAULT 0,failed_at timestamptz,UNIQUE(user_id,slot_at));
GRANT SELECT ON public.staff_digest_outbox TO authenticated; GRANT ALL ON public.staff_digest_outbox TO service_role;
ALTER TABLE public.staff_digest_outbox ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_digest ON public.staff_digest_outbox FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE FUNCTION public.overdue_digest_items(_on date) RETURNS TABLE(user_id uuid,item jsonb) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$
SELECT t.assignee_id,jsonb_build_object('kind','launch','id',t.id,'name',t.name,'hotel',c.hotel_name,'due',t.due_date,'link','/launches/'||t.launch_id)
FROM client_tasks t JOIN clients c ON c.id=t.client_id JOIN client_launches l ON l.id=t.launch_id WHERE t.assignee_id IS NOT NULL AND t.due_date<_on AND t.status NOT IN('done','not_applicable') AND l.status IN('active','live','offboarding') AND NOT c.is_demo AND NOT task_gate_a_locked(t.id)
UNION ALL SELECT r.owner_id,jsonb_build_object('kind','monthly','id',r.id,'name',a.name,'hotel',c.hotel_name,'due',r.due_date,'link','/my-tasks') FROM recurring_tasks r JOIN activity_items a ON a.id=r.item_id JOIN activity_plans ap ON ap.id=r.plan_id JOIN client_pipelines cp ON cp.id=ap.client_pipeline_id JOIN clients c ON c.id=cp.client_id WHERE r.owner_id IS NOT NULL AND r.due_date<_on AND r.status NOT IN('done','closed','not_applicable','missed') AND NOT c.is_demo AND NOT client_on_hold(c.id)
$$;
REVOKE ALL ON FUNCTION public.overdue_digest_items(date) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.overdue_digest_items(date) TO service_role;
CREATE FUNCTION public.queue_overdue_digest(_at timestamptz DEFAULT now()) RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE local_at timestamp:=_at AT TIME ZONE 'Asia/Kolkata'; r record; i uuid; n int:=0; b text; BEGIN
IF extract(isodow FROM local_at)=7 OR EXISTS(SELECT 1 FROM activity_holidays WHERE day=local_at::date) OR local_at::time NOT IN('11:00'::time,'15:00'::time,'18:00'::time) THEN RETURN 0; END IF;
FOR r IN SELECT x.user_id,p.email,jsonb_agg(x.item ORDER BY x.item->>'due',x.item->>'hotel',x.item->>'name') items FROM overdue_digest_items(local_at::date) x JOIN profiles p ON p.id=x.user_id AND p.status='active' WHERE NOT has_role(p.id,'client') GROUP BY x.user_id,p.email LOOP
SELECT string_agg((v->>'hotel')||' · '||(v->>'name')||' · due '||(v->>'due'),E'\n') INTO b FROM jsonb_array_elements(r.items) v;
i:=NULL; INSERT INTO staff_digest_outbox(user_id,slot_at,to_address,subject,body,items,held) VALUES(r.user_id,_at,r.email,'Your overdue tasks · '||to_char(local_at,'DD Mon HH24:MI'),b,r.items,true) ON CONFLICT(user_id,slot_at) DO NOTHING RETURNING id INTO i;
IF i IS NOT NULL THEN INSERT INTO notifications(user_id,title,body,link,kind) VALUES(r.user_id,'Your overdue tasks · '||jsonb_array_length(r.items),b,'/my-tasks','overdue_digest'); n:=n+1; END IF; END LOOP; RETURN n; END $$;
REVOKE ALL ON FUNCTION public.queue_overdue_digest(timestamptz) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.queue_overdue_digest(timestamptz) TO service_role;
CREATE OR REPLACE FUNCTION public.escalate_overdue_tasks() RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN RETURN public.escalate_blocked_tasks(); END $$;
COMMENT ON FUNCTION public.escalate_overdue_tasks() IS 'Legacy overdue alerts retired by Q46; blocked escalation retained. Personal overdue items use queue_overdue_digest.';
CREATE FUNCTION public.run_overdue_digest() RETURNS integer LANGUAGE sql SECURITY DEFINER SET search_path=public AS $$ SELECT queue_overdue_digest(date_trunc('minute',now())) $$;
REVOKE ALL ON FUNCTION public.run_overdue_digest() FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.run_overdue_digest() TO service_role;
CREATE FUNCTION public.live_checklist_guard() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NEW.source_row IS NOT NULL AND NEW.activated_at IS NULL AND NEW.status IN('active','live','on_hold') THEN NEW.no_launch_checklist:=true; END IF; IF TG_OP='UPDATE' AND OLD.no_launch_checklist AND NOT NEW.no_launch_checklist THEN RAISE EXCEPTION 'Existing live clients remain Live, no checklist'; END IF; RETURN NEW; END $$;
REVOKE ALL ON FUNCTION public.live_checklist_guard() FROM PUBLIC,anon,authenticated;
CREATE TRIGGER a_live_checklist_guard BEFORE INSERT OR UPDATE ON public.client_launches FOR EACH ROW EXECUTE FUNCTION public.live_checklist_guard();